using System.Collections;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "InstabilityAction", menuName = "Data/Battle/Battle Actions/Enemy/Instability Action")]
public class InstabilityAction : BattleAction
{
	public override void CastTarget(GameObject target, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(InstabilityAnimationCoroutine(target));
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	private IEnumerator InstabilityAnimationCoroutine(GameObject target)
	{
		target.GetComponent<SpriteControl>().PlayAnimationForced(AnimationType.DieIdle, AnimationChangeType.StayInTheNewAnimationLooping);
		yield return new WaitForSeconds(0.5f);
		target.GetComponent<CorruptedAnimalCorruptionStats>().InstantlyDefeatEnemy();
		SpawnVFX(GetVFXOwnerPosition(target), 5f);
	}
}
